"use strict";
// Loads its parts with a computed specifier: a Node island.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const tag = load(["./", "tag"].join(""));

exports.json = () => (req, res) => `${tag}:${req}:${res}`;
exports.accept = (handle) => `handler ${typeof handle} ${tag}`;
